N=22
grid=[[0]*N for _ in range(N)]
def put(r,c,v):
    assert 0<=r<N and 0<=c<N,(r,c,v)
    if grid[r][c] not in (0,v) and v != 2 and grid[r][c]!=2:
        raise ValueError((r,c,grid[r][c],v))
    # markers coincide legitimately; colored cells don't overlap markers
    if v==2 and grid[r][c]!=0: return
    grid[r][c]=v
